/* Verse Games: THE WHOLE COUNSEL · Acts chapters 21-25
   Verse text is filled/verified from the KJV by tools/fill-verses.js */
VG.registerBibleChapters("acts", [
{n:21, name:"Bound for Jerusalem",
 seal:{ref:"Acts 21:13",verse:"Then Paul answered, What mean ye to weep and to break mine heart? for I am ready not to be bound only, but also to die at Jerusalem for the name of the Lord Jesus."},
 facts:[
  "Did you know Philip the evangelist had four daughters who prophesied? This is the same Philip who preached to the Ethiopian eunuch in Acts 8, still serving the gospel at Caesarea years later (Acts 21:8-9).",
  "Did you know Agabus had prophesied once before? In Acts 11 he foretold the great famine in the days of Claudius. Now he binds his own hands and feet with Paul's girdle to picture the arrest waiting at Jerusalem (Acts 21:10-11).",
  "Did you know the Jerusalem riot began with a mistaken sighting? Jews from Asia had seen Trophimus the Ephesian with Paul in the city, and only supposed Paul had brought him past the temple barrier (Acts 21:27-29)."
 ],
 questions:[
  {q:"After leaving Ephesus, what course did Paul's company sail?", options:["They came with a straight course unto Coos, and the day following unto Rhodes, and from thence unto Patara","They sailed first to Athens, then to Corinth, then to Rome","They crossed to Alexandria, then coasted to Cyrene","They sailed straight to Caesarea without stopping"], a:0, ref:"Acts 21:1",verse:"And it came to pass, that after we were gotten from them, and had launched, we came with a straight course unto Coos, and the day following unto Rhodes, and from thence unto Patara:", insight:"Luke notes the straight course, as if even the wind was in a hurry; when God sets the course, the sailing holds true."},
  {q:"Why did Paul's ship put in at Tyre?", options:["There the ship was to unlade her burden","Paul had promised to preach there a month","A storm drove them into the harbor","The crew needed to take on fresh water"], a:0, ref:"Acts 21:3",verse:"Now when we had discovered Cyprus, we left it on the left hand, and sailed into Syria, and landed at Tyre: for there the ship was to unlade her burden.", insight:"Even apostolic journeys bend to cargo schedules; God works through ordinary logistics."},
  {q:"How long did Paul tarry with the disciples at Tyre?", options:["Seven days","Three days","One day","Forty days"], a:0, ref:"Acts 21:4",verse:"And finding disciples, we tarried there seven days: who said to Paul through the Spirit, that he should not go up to Jerusalem.", insight:"Seven days with strangers who became family; the church makes every port a home."},
  {q:"What did the disciples at Tyre say to Paul through the Spirit?", options:["That he should not go up to Jerusalem","That he should sail on to Rome","That he should return to Antioch","That he should wait for Barnabas"], a:0, ref:"Acts 21:4",verse:"And finding disciples, we tarried there seven days: who said to Paul through the Spirit, that he should not go up to Jerusalem.", insight:"The Spirit warned of suffering ahead; love always wants to spare us the road God has set."},
  {q:"What did the Tyrian believers do on the shore as Paul departed?", options:["They kneeled down on the shore, and prayed","They sang a hymn of farewell","They broke bread together","They anointed him with oil"], a:0, ref:"Acts 21:5",verse:"And when we had accomplished those days, we departed and went our way; and they all brought us on our way, with wives and children, till we were out of the city: and we kneeled down on the shore, and prayed.", insight:"Kneeling on a beach with wives and children; prayer hallows every parting."},
  {q:"At Caesarea, into whose house did Paul's company enter?", options:["Philip the evangelist, which was one of the seven","Cornelius the centurion","Mnason of Cyprus","Agabus the prophet"], a:0, ref:"Acts 21:8",verse:"And the next day we that were of Paul’s company departed, and came unto Caesarea: and we entered into the house of Philip the evangelist, which was one of the seven; and abode with him.", insight:"Philip the evangelist opened his home; hospitality is the gospel with the door open."},
  {q:"What is said of Philip's four daughters?", options:["Virgins, which did prophesy","Widows, which did serve tables","Wives, which did sing psalms","Teachers, which did write letters"], a:0, ref:"Acts 21:9",verse:"And the same man had four daughters, virgins, which did prophesy.", insight:"Four daughters who prophesied; God pours His Spirit on sons and daughters alike."},
  {q:"Who came down from Judaea while Paul tarried at Caesarea?", options:["A certain prophet, named Agabus","Barnabas of Cyprus","Silas the scribe","Timothy of Lystra"], a:0, ref:"Acts 21:10",verse:"And as we tarried there many days, there came down from Judaea a certain prophet, named Agabus.", insight:"Agabus came a long way to deliver a hard word; true prophets do not flatter."},
  {q:"What did Agabus do with Paul's girdle?", options:["He bound his own hands and feet with it","He cast it into the sea","He gave it to Philip's daughters","He hung it on the city gate"], a:0, ref:"Acts 21:11",verse:"And when he was come unto us, he took Paul’s girdle, and bound his own hands and feet, and said, Thus saith the Holy Ghost, So shall the Jews at Jerusalem bind the man that owneth this girdle, and shall deliver him into the hands of the Gentiles.", insight:"He acted the prophecy before he spoke it; sometimes the body preaches first."},
  {q:"What did Agabus say the Jews at Jerusalem would do to the girdle's owner?", options:["Bind him, and deliver him into the hands of the Gentiles","Stone him outside the city","Drive him back to Tarsus","Hand him to the chief captain for a reward"], a:0, ref:"Acts 21:11",verse:"And when he was come unto us, he took Paul’s girdle, and bound his own hands and feet, and said, Thus saith the Holy Ghost, So shall the Jews at Jerusalem bind the man that owneth this girdle, and shall deliver him into the hands of the Gentiles.", insight:"Bound by Jews, delivered to Gentiles; the prophecy named both chains in one breath."},
  {q:"When they heard Agabus, what did Paul's companions beg him?", options:["Not to go up to Jerusalem","To take them with him","To write to the churches first","To appeal to Caesar at once"], a:0, ref:"Acts 21:12",verse:"And when we heard these things, both we, and they of that place, besought him not to go up to Jerusalem.", insight:"Their tears were love, but Paul's course was set; love sometimes has to let go."},
  {q:"What was Paul ready to do at Jerusalem?", options:["Not to be bound only, but also to die for the name of the Lord Jesus","To preach until the rulers believed","To buy his freedom with gifts","To hide until the feast was past"], a:0, ref:"Acts 21:13",verse:"Then Paul answered, What mean ye to weep and to break mine heart? for I am ready not to be bound only, but also to die at Jerusalem for the name of the Lord Jesus.", insight:"Ready not only for chains but for death; he counted the cost and found Christ worth it."},
  {q:"When Paul would not be persuaded, what did the brethren say?", options:["The will of the Lord be done","Go with God, and return soon","We will pray night and day","The Lord preserve thee"], a:0, ref:"Acts 21:14",verse:"And when he would not be persuaded, we ceased, saying, The will of the Lord be done.", insight:"They stopped arguing and surrendered; 'the will of the Lord be done' is faith's last word."},
  {q:"Who was Mnason?", options:["An old disciple of Cyprus, with whom they should lodge","A chief priest of Jerusalem","A Roman centurion of the band","A prophet from Judaea"], a:0, ref:"Acts 21:16",verse:"There went with us also certain of the disciples of Caesarea, and brought with them one Mnason of Cyprus, an old disciple, with whom we should lodge.", insight:"An old disciple with a house in Jerusalem; long faithfulness makes room for others."},
  {q:"How did James describe the believing Jews at Jerusalem?", options:["Many thousands which believe, and zealous of the law","A few hundred who kept the feasts","Thousands who had forsaken Moses","Many who feared the Romans"], a:0, ref:"Acts 21:20",verse:"And when they heard it, they glorified the Lord, and said unto him, Thou seest, brother, how many thousands of Jews there are which believe; and they are all zealous of the law:", insight:"Thousands believed and still loved the law; the gospel did not ask them to stop being Jews."},
  {q:"How many men at Jerusalem had a vow on them?", options:["Four","Two","Seven","Twelve"], a:0, ref:"Acts 21:23",verse:"Do therefore this that we say to thee: We have four men which have a vow on them;", insight:"Four men, one vow each; James turned numbers into a plan for peace."},
  {q:"Who stirred up the people against Paul in the temple?", options:["The Jews which were of Asia","The priests of the temple","The Roman soldiers","The Sadducees of the council"], a:0, ref:"Acts 21:27",verse:"And when the seven days were almost ended, the Jews which were of Asia, when they saw him in the temple, stirred up all the people, and laid hands on him,", insight:"Men from Paul's own mission field became his accusers; no field is safe from old enemies."},
  {q:"Whom had the accusers seen with Paul in the city?", options:["Trophimus an Ephesian","Timothy of Lystra","Titus the Greek","Erastus of Corinth"], a:0, ref:"Acts 21:29",verse:"(For they had seen before with him in the city Trophimus an Ephesian, whom they supposed that Paul had brought into the temple.)", insight:"They saw Trophimus in the city and imagined him in the temple; suspicion builds cases out of shadows."},
  {q:"Whom did the chief captain mistake Paul for?", options:["That Egyptian who led four thousand murderers into the wilderness","A zealot chief of Jerusalem","A runaway slave of Cilicia","A false prophet of Samaria"], a:0, ref:"Acts 21:38",verse:"Art not thou that Egyptian, which before these days madest an uproar, and leddest out into the wilderness four thousand men that were murderers?", insight:"Rome's files were full of rebels; Paul's quiet courage did not match the description."},
  {q:"How did Paul answer the chief captain?", options:["I am a Jew of Tarsus, a city in Cilicia, a citizen of no mean city","I am a Roman born in Jerusalem","I am a Pharisee of the tribe of Benjamin","I am a tentmaker of no account"], a:0, ref:"Acts 21:39",verse:"But Paul said, I am a man which am a Jew of Tarsus, a city in Cilicia, a citizen of no mean city: and, I beseech thee, suffer me to speak unto the people.", insight:"A citizen of no mean city; Paul owned his story without shame."}
 ]},
{n:22, name:"Paul's Defense on the Stairs",
 seal:{ref:"Acts 22:16",verse:"And now why tarriest thou? arise, and be baptized, and wash away thy sins, calling on the name of the Lord."},
 facts:[
  "Did you know Paul won his hearing by speaking Hebrew? The mob had been screaming 'Away with him,' but when he addressed them in their own tongue, 'they kept the more silence' (Acts 22:2).",
  "Did you know Paul was born a Roman citizen? The chief captain had bought his freedom 'with a great sum,' but Paul could answer, 'But I was free born' (Acts 22:28). That birthright stopped the scourging.",
  "Did you know Luke tells Paul's conversion three times? Acts 9 gives the event, Acts 22 gives Paul's own defense of it, and Acts 26 tells it again before a king. The story never changes; only the hearers do."
 ],
 questions:[
  {q:"How did Paul begin his defense on the stairs?", options:["Men, brethren, and fathers, hear ye my defence which I make now unto you","Sirs, be of good cheer, for I believe God","Ye men of Athens, I perceive ye are religious","People of Jerusalem, hear the words of a Roman"], a:0, ref:"Acts 22:1",verse:"Men, brethren, and fathers, hear ye my defence which I make now unto you.", insight:"He called them brethren before they called him criminal; respect opens ears that anger shuts."},
  {q:"Why did the crowd keep the more silence?", options:["He spake unto them in the Hebrew tongue","He lifted up his chained hands","He wept aloud before them","He spoke in the Latin tongue"], a:0, ref:"Acts 22:2",verse:"(And when they heard that he spake in the Hebrew tongue to them, they kept the more silence: and he saith,)", insight:"Their own tongue quieted them; the gospel always sounds best at home."},
  {q:"Where was Paul born?", options:["In Tarsus, a city in Cilicia","In Damascus of Syria","In Alexandria of Egypt","In Jerusalem of Judea"], a:0, ref:"Acts 22:3",verse:"I am verily a man which am a Jew, born in Tarsus, a city in Cilicia, yet brought up in this city at the feet of Gamaliel, and taught according to the perfect manner of the law of the fathers, and was zealous toward God, as ye all are this day.", insight:"Tarsus, a city in Cilicia; God can raise an apostle anywhere, even far from Jerusalem."},
  {q:"At whose feet was Paul brought up?", options:["Gamaliel","Hillel","Nicodemus","Shammai"], a:0, ref:"Acts 22:3",verse:"I am verily a man which am a Jew, born in Tarsus, a city in Cilicia, yet brought up in this city at the feet of Gamaliel, and taught according to the perfect manner of the law of the fathers, and was zealous toward God, as ye all are this day.", insight:"Gamaliel, the honored teacher; the finest schooling bowed at last to Christ."},
  {q:"What did Ananias say Paul would be?", options:["His witness unto all men of what thou hast seen and heard","A priest unto the Gentiles","A scribe of the law in Jerusalem","A teacher of the synagogue"], a:0, ref:"Acts 22:15",verse:"For thou shalt be his witness unto all men of what thou hast seen and heard.", insight:"A witness of what he had seen and heard; testimony, not theory, is the apostle's work."},
  {q:"How far had Paul gone in persecuting this way?", options:["Unto the death, binding and delivering into prisons both men and women","Unto fines, taxing the believers heavily","Unto exile, driving them from Judea","Unto mockery, shaming them in the synagogues"], a:0, ref:"Acts 22:4",verse:"And I persecuted this way unto the death, binding and delivering into prisons both men and women.", insight:"Unto the death; the chief of persecutors became the chief of preachers."},
  {q:"What had Paul received from the high priest and the elders?", options:["Letters unto the brethren, to bring the bound to Jerusalem","Money for the poor of Damascus","Orders to build new synagogues","Leave to preach in the temple"], a:0, ref:"Acts 22:5",verse:"As also the high priest doth bear me witness, and all the estate of the elders: from whom also I received letters unto the brethren, and went to Damascus, to bring them which were there bound unto Jerusalem, for to be punished.", insight:"Letters of authority became his shame; what we boast in while sinning, we confess in grace."},
  {q:"At what time of day did the light shine around Paul?", options:["About noon","At midnight","At the dawn","At the sunset"], a:0, ref:"Acts 22:6",verse:"And it came to pass, that, as I made my journey, and was come nigh unto Damascus about noon, suddenly there shone from heaven a great light round about me.", insight:"About noon, when the sun is brightest; Christ outshone the noonday sun."},
  {q:"What did the voice from heaven say?", options:["Saul, Saul, why persecutest thou me?","Saul, Saul, why fleest thou from me?","Paul, arise and follow me","Saul, go and preach to the Gentiles"], a:0, ref:"Acts 22:7",verse:"And I fell unto the ground, and heard a voice saying unto me, Saul, Saul, why persecutest thou me?", insight:"Why persecutest thou me; Christ takes the Church's wounds as His own."},
  {q:"How did the Lord name Himself to Paul?", options:["I am Jesus of Nazareth, whom thou persecutest","I am the God of Abraham thy father","I am an angel of the Lord","I am the Holy Ghost from heaven"], a:0, ref:"Acts 22:8",verse:"And I answered, Who art thou, Lord? And he said unto me, I am Jesus of Nazareth, whom thou persecutest.", insight:"Jesus of Nazareth; the despised name from the despised town was the Lord of glory."},
  {q:"What did Paul's companions experience on the road?", options:["They saw the light, and were afraid, but heard not the voice","They heard the voice, but saw no light","They fell asleep and dreamed","They saw nothing and heard nothing"], a:0, ref:"Acts 22:9",verse:"And they that were with me saw indeed the light, and were afraid; but they heard not the voice of him that spake to me.", insight:"They saw the light but missed the voice; nearness to grace is not the same as hearing it."},
  {q:"Why was Paul led by the hand into Damascus?", options:["He could not see for the glory of that light","He was lame from the fall","The road was dark with night","It was the custom for the blind"], a:0, ref:"Acts 22:11",verse:"And when I could not see for the glory of that light, being led by the hand of them that were with me, I came into Damascus.", insight:"Blinded by glory, led like a child; the strong man learned to be guided."},
  {q:"How is Ananias described?", options:["A devout man according to the law, having a good report of all the Jews","A Roman centurion of the Italian band","A tax collector turned disciple","A young man of the synagogue"], a:0, ref:"Acts 22:12",verse:"And one Ananias, a devout man according to the law, having a good report of all the Jews which dwelt there,", insight:"Devout and well spoken of; God chose a quiet, trusted man for a turning point errand."},
  {q:"What were Ananias's first words to Paul?", options:["Brother Saul, receive thy sight","Depart from me, thou persecutor","Go thy way in peace","The Lord rebuke thee, Saul"], a:0, ref:"Acts 22:13",verse:"Came unto me, and stood, and said unto me, Brother Saul, receive thy sight. And the same hour I looked up upon him.", insight:"Brother Saul; grace renamed the enemy a brother before his eyes were opened."},
  {q:"For what had God chosen Paul, according to Ananias?", options:["To know His will, and see that Just One, and hear the voice of His mouth","To rule the churches of Asia","To write the law anew","To judge the twelve tribes"], a:0, ref:"Acts 22:14",verse:"And he said, The God of our fathers hath chosen thee, that thou shouldest know his will, and see that Just One, and shouldest hear the voice of his mouth.", insight:"To know, to see, to hear; calling begins with knowing God, not doing for God."},
  {q:"What did Ananias urge Paul to do without delay?", options:["Arise, and be baptized, and wash away thy sins, calling on the name of the Lord","Return to Jerusalem and confess","Offer a sacrifice in the temple","Wait forty days and pray"], a:0, ref:"Acts 22:16",verse:"And now why tarriest thou? arise, and be baptized, and wash away thy sins, calling on the name of the Lord.", insight:"Why tarriest thou; obedience delayed is obedience weakened."},
  {q:"What warning did the Lord give Paul in the temple?", options:["Make haste, and get thee quickly out of Jerusalem, for they will not receive thy testimony","Stay and preach boldly in the synagogues","Return to Tarsus and wait","Go at once to Rome"], a:0, ref:"Acts 22:18",verse:"And saw him saying unto me, Make haste, and get thee quickly out of Jerusalem: for they will not receive thy testimony concerning me.", insight:"Get thee quickly out; God sometimes saves His servants by hurrying them away."},
  {q:"What part did Paul confess in Stephen's death?", options:["He was standing by, consenting, and kept the raiment of them that slew him","He cast the first stone","He ordered the stoning","He prayed for Stephen's death"], a:0, ref:"Acts 22:20",verse:"And when the blood of thy martyr Stephen was shed, I also was standing by, and consenting unto his death, and kept the raiment of them that slew him.", insight:"He kept the coats; the keeper of the murderers' clothes became the martyr's fellow."},
  {q:"What mission did the Lord give Paul?", options:["Depart, for I will send thee far hence unto the Gentiles","Preach to the Jews only","Return to Arabia in silence","Build churches throughout Judea"], a:0, ref:"Acts 22:21",verse:"And he said unto me, Depart: for I will send thee far hence unto the Gentiles.", insight:"Far hence unto the Gentiles; the mission that would fill the world began with one word, Depart."},
  {q:"How did Paul answer the chief captain's bought citizenship?", options:["But I was free born","I bought mine with service","Caesar himself gave it me","My father purchased it"], a:0, ref:"Acts 22:28",verse:"And the chief captain answered, With a great sum obtained I this freedom. And Paul said, But I was free born.", insight:"Free born; earthly citizenship stopped the scourge, but his heaven born freedom carried the gospel."}
 ]},
{n:23, name:"Before the Council",
 seal:{ref:"Acts 23:11",verse:"And the night following the Lord stood by him, and said, Be of good cheer, Paul: for as thou hast testified of me in Jerusalem, so must thou bear witness also at Rome."},
 facts:[
  "Did you know Paul's nephew saved his life? The only mention of Paul's family outside his own words is his sister's son, who slipped into the castle to warn him of the ambush (Acts 23:16).",
  "Did you know a Roman officer's letter is quoted word for word? Claudius Lysias wrote to 'the most excellent governor Felix,' and Luke preserves the whole letter in Acts 23:26-30.",
  "Did you know the Lord's promise came on Paul's darkest night? 'As thou hast testified of me in Jerusalem, so must thou bear witness also at Rome' (Acts 23:11). The road to Rome began in chains."
 ],
 questions:[
  {q:"How did Paul say he had lived before God?", options:["In all good conscience before God until this day","Without fault since his youth","In the favor of the high priest","Beyond the reach of the law"], a:0, ref:"Acts 23:1",verse:"And Paul, earnestly beholding the council, said, Men and brethren, I have lived in all good conscience before God until this day.", insight:"A good conscience until this day; integrity is the best opening statement."},
  {q:"What did the high priest Ananias command?", options:["To smite Paul on the mouth","To bind him with chains","To cast him into prison","To strip him of his clothes"], a:0, ref:"Acts 23:2",verse:"And the high priest Ananias commanded them that stood by him to smite him on the mouth.", insight:"Smitten on the mouth for speaking truth; the court struck first because it had no answer."},
  {q:"What did Paul call Ananias?", options:["Thou whited wall","Thou blind guide","Thou painted sepulchre","Thou son of Belial"], a:0, ref:"Acts 23:3",verse:"Then said Paul unto him, God shall smite thee, thou whited wall: for sittest thou to judge me after the law, and commandest me to be smitten contrary to the law?", insight:"A whited wall, fair outside and foul within; Paul named the hypocrisy he saw."},
  {q:"What did Paul say when he learned Ananias was the high priest?", options:["I wist not, brethren: for it is written, Thou shalt not speak evil of the ruler of thy people","I spoke only what is true","God will judge between us","I appeal to Caesar"], a:0, ref:"Acts 23:5",verse:"Then said Paul, I wist not, brethren, that he was the high priest: for it is written, Thou shalt not speak evil of the ruler of thy people.", insight:"He owned his mistake and quoted Scripture; the quickest apology is the truest."},
  {q:"What cry divided the council?", options:["I am a Pharisee, the son of a Pharisee: of the hope and resurrection of the dead I am called in question","I am a Roman, and uncondemned","I appeal unto Caesar","God shall smite thee, thou whited wall"], a:0, ref:"Acts 23:6",verse:"But when Paul perceived that the one part were Sadducees, and the other Pharisees, he cried out in the council, Men and brethren, I am a Pharisee, the son of a Pharisee: of the hope and resurrection of the dead I am called in question.", insight:"One sentence split the court; truth divides before it conquers."},
  {q:"What three things do the Sadducees deny?", options:["Resurrection, angel, and spirit","Heaven, hell, and judgment","Law, prophets, and psalms","Moses, Aaron, and Miriam"], a:0, ref:"Acts 23:8",verse:"For the Sadducees say that there is no resurrection, neither angel, nor spirit: but the Pharisees confess both.", insight:"No resurrection, no angel, no spirit; unbelief always shrinks the world."},
  {q:"What did the Pharisees' scribes conclude about Paul?", options:["We find no evil in this man","He is worthy of death","He blasphemes Moses","He must be silenced"], a:0, ref:"Acts 23:9",verse:"And there arose a great cry: and the scribes that were of the Pharisees’ part arose, and strove, saying, We find no evil in this man: but if a spirit or an angel hath spoken to him, let us not fight against God.", insight:"Even his enemies' party found no evil in him; a clean life baffles accusers."},
  {q:"Why did the chief captain seize Paul by force from the council?", options:["He feared Paul would be pulled in pieces by them","Felix had ordered it","The council asked him to","Paul had appealed to Caesar"], a:0, ref:"Acts 23:10",verse:"And when there arose a great dissension, the chief captain, fearing lest Paul should have been pulled in pieces of them, commanded the soldiers to go down, and to take him by force from among them, and to bring him into the castle.", insight:"Pulled in pieces; Rome's iron hand became God's shield that day."},
  {q:"What did the Lord say to Paul that night in the castle?", options:["Be of good cheer, Paul: for as thou hast testified of me in Jerusalem, so must thou bear witness also at Rome","Fear not, Paul, for I have many people in this city","Depart quickly, for they seek thy life","Be still, and know that I am God"], a:0, ref:"Acts 23:11",verse:"And the night following the Lord stood by him, and said, Be of good cheer, Paul: for as thou hast testified of me in Jerusalem, so must thou bear witness also at Rome.", insight:"Be of good cheer; the darkest night in the castle carried the brightest promise, Rome."},
  {q:"What curse did the conspirators lay on themselves?", options:["To neither eat nor drink till they had killed Paul","To fast forty days and nights","To shave their heads in mourning","To leave Jerusalem forever"], a:0, ref:"Acts 23:12",verse:"And when it was day, certain of the Jews banded together, and bound themselves under a curse, saying that they would neither eat nor drink till they had killed Paul.", insight:"They cursed their own appetites; hatred makes men swear against themselves."},
  {q:"How many men joined the conspiracy against Paul?", options:["More than forty","Twelve","Seventy","Four thousand"], a:0, ref:"Acts 23:13",verse:"And they were more than forty which had made this conspiracy.", insight:"More than forty against one prisoner; God was outnumbered and unafraid."},
  {q:"What was the plot's plan?", options:["Ask the chief captain to bring Paul down, then kill him on the way","Poison his food in the castle","Bribe the guards at midnight","Stone him in the temple courts"], a:0, ref:"Acts 23:15",verse:"Now therefore ye with the council signify to the chief captain that he bring him down unto you to morrow, as though ye would enquire something more perfectly concerning him: and we, or ever he come near, are ready to kill him.", insight:"A hearing was the bait and murder the hook; evil loves a respectable cover."},
  {q:"Who overheard the ambush plot?", options:["Paul's sister's son","A Roman soldier","One of the Pharisees","A servant of the high priest"], a:0, ref:"Acts 23:16",verse:"And when Paul’s sister’s son heard of their lying in wait, he went and entered into the castle, and told Paul.", insight:"His sister's son; God plants family in the very city of your enemies."},
  {q:"How did the chief captain receive the young man?", options:["He took him by the hand, and heard him aside privately","He had him examined by scourging","He sent him at once to Felix","He bound him with chains"], a:0, ref:"Acts 23:19",verse:"Then the chief captain took him by the hand, and went with him aside privately, and asked him, What is that thou hast to tell me?", insight:"He took him by the hand; gentleness in a soldier opened the way for truth."},
  {q:"What charge did the chief captain give the young man?", options:["Tell no man that thou hast shewed these things to me","Go and warn the council","Stay hidden in the castle","Write it all to Felix"], a:0, ref:"Acts 23:22",verse:"So the chief captain then let the young man depart, and charged him, See thou tell no man that thou hast shewed these things to me.", insight:"Tell no man; wisdom keeps some rescues quiet."},
  {q:"What escort did the chief captain send with Paul to Caesarea?", options:["Two hundred soldiers, seventy horsemen, and two hundred spearmen","Twelve centurions and their servants","Forty archers of the guard","A full Roman legion"], a:0, ref:"Acts 23:23",verse:"And he called unto him two centurions, saying, Make ready two hundred soldiers to go to Caesarea, and horsemen threescore and ten, and spearmen two hundred, at the third hour of the night;", insight:"Four hundred and seventy men for one apostle; heaven's arithmetic beats earth's."},
  {q:"To whom was Paul to be brought safe?", options:["Felix the governor","King Agrippa","Caesar Augustus","The high priest"], a:0, ref:"Acts 23:24",verse:"And provide them beasts, that they may set Paul on, and bring him safe unto Felix the governor.", insight:"Safe unto Felix; the long road to Rome began with a midnight ride."},
  {q:"How did the official letter begin?", options:["Claudius Lysias unto the most excellent governor Felix sendeth greeting","Felix, most noble governor, from thy servant Lysias","To Caesar Augustus, from Claudius Lysias","Greetings from the council at Jerusalem"], a:0, ref:"Acts 23:26",verse:"Claudius Lysias unto the most excellent governor Felix sendeth greeting.", insight:"Claudius Lysias; even a Roman's name is preserved when it serves God's prisoner."},
  {q:"What was Lysias's verdict on the charges?", options:["Questions of their law, nothing worthy of death or of bonds","Treason against Caesar","Blasphemy worthy of death","Sedition throughout the empire"], a:0, ref:"Acts 23:29",verse:"Whom I perceived to be accused of questions of their law, but to have nothing laid to his charge worthy of death or of bonds.", insight:"Nothing worthy of death or of bonds; the empire's own officer cleared him."},
  {q:"Where did the soldiers bring Paul by night?", options:["Antipatris","Joppa","Lydda","Emmaus"], a:0, ref:"Acts 23:31",verse:"Then the soldiers, as it was commanded them, took Paul, and brought him by night to Antipatris.", insight:"By night to Antipatris; God moves His servants under cover of darkness."}
 ]},
{n:24, name:"Paul Before Felix",
 seal:{ref:"Acts 24:16",verse:"And herein do I exercise myself, to have always a conscience void of offence toward God, and toward men."},
 facts:[
  "Did you know Tertullus praised Felix for 'great quietness,' yet history remembers Felix as a harsh governor whose misrule helped spark the Jewish revolt? Flattery rarely survives the facts (Acts 24:2-3).",
  "Did you know 'the sect of the Nazarenes' appears only here in Scripture? The accusers meant it as an insult, but the name points back to Jesus of Nazareth (Acts 24:5).",
  "Did you know Felix trembled at a prisoner's preaching? As Paul reasoned of righteousness, temperance, and judgment to come, the governor shook, then put him off to 'a convenient season' (Acts 24:25). Convenient seasons seldom come."
 ],
 questions:[
  {q:"Who came down to accuse Paul before Felix?", options:["Ananias the high priest, the elders, and Tertullus the orator","The chief captain and his centurions","King Agrippa and Bernice","The scribes of the Pharisees"], a:0, ref:"Acts 24:1",verse:"And after five days Ananias the high priest descended with the elders, and with a certain orator named Tertullus, who informed the governor against Paul.", insight:"The high priest hired an orator; when truth is thin, men rent eloquence."},
  {q:"How did Tertullus begin his accusation?", options:["With flattery of Felix's peace and worthy deeds","With a reading of the law","With tears for the nation","With an oath by Caesar"], a:0, ref:"Acts 24:2",verse:"And when he was called forth, Tertullus began to accuse him, saying, Seeing that by thee we enjoy great quietness, and that very worthy deeds are done unto this nation by thy providence,", insight:"Great quietness, worthy deeds; flattery is the doormat of false accusation."},
  {q:"What three charges did Tertullus lay against Paul?", options:["A pestilent fellow, a mover of sedition, and a ringleader of the Nazarenes","A thief, a liar, and a murderer","A tax dodger, a deserter, and a spy","A blasphemer, a sorcerer, and a traitor"], a:0, ref:"Acts 24:5",verse:"For we have found this man a pestilent fellow, and a mover of sedition among all the Jews throughout the world, and a ringleader of the sect of the Nazarenes:", insight:"Pestilent fellow; when they cannot prove the crime, they poison the name."},
  {q:"What name did the accusers give the Christians?", options:["The sect of the Nazarenes","The way of the Galileans","The school of the prophets","The assembly of the saints"], a:0, ref:"Acts 24:5",verse:"For we have found this man a pestilent fellow, and a mover of sedition among all the Jews throughout the world, and a ringleader of the sect of the Nazarenes:", insight:"The sect of the Nazarenes; meant as a slur, it pointed straight to Jesus of Nazareth."},
  {q:"What did they claim Paul had tried to do?", options:["Profane the temple","Burn the Scriptures","Bribe the temple guards","Flee to Rome by night"], a:0, ref:"Acts 24:6",verse:"Who also hath gone about to profane the temple: whom we took, and would have judged according to our law.", insight:"Profane the temple; the charge was built on the same mistake as the riot."},
  {q:"Why did Paul answer Felix cheerfully?", options:["Felix had been many years a judge unto the nation","Felix was a believer in Christ","Felix had promised him freedom","Felix was a friend of Gamaliel"], a:0, ref:"Acts 24:10",verse:"Then Paul, after that the governor had beckoned unto him to speak, answered, Forasmuch as I know that thou hast been of many years a judge unto this nation, I do the more cheerfully answer for myself:", insight:"Many years a judge; Paul respected the office even when the officer was corrupt."},
  {q:"How many days had passed since Paul went up to Jerusalem?", options:["Twelve","Five","Forty","Seventy"], a:0, ref:"Acts 24:11",verse:"Because that thou mayest understand, that there are yet but twelve days since I went up to Jerusalem for to worship.", insight:"But twelve days; the whole case rested on less than a fortnight."},
  {q:"What could the accusers not show Paul doing?", options:["Disputing in the temple or raising up the people","Paying the temple tax","Eating with Gentiles","Preaching on the Sabbath"], a:0, ref:"Acts 24:12",verse:"And they neither found me in the temple disputing with any man, neither raising up the people, neither in the synagogues, nor in the city:", insight:"Neither disputing nor raising the people; innocence leaves no footprints."},
  {q:"What did Paul say of the charges?", options:["They cannot prove the things whereof they now accuse me","They are partly true","They concern only the Gentiles","They were withdrawn already"], a:0, ref:"Acts 24:13",verse:"Neither can they prove the things whereof they now accuse me.", insight:"Neither can they prove; unproven charges are just loud opinions."},
  {q:"What did Paul openly confess?", options:["He worshipped the God of his fathers, believing all in the law and the prophets","He had forsaken the law of Moses","He followed the wisdom of the Greeks","He served Caesar above all"], a:0, ref:"Acts 24:14",verse:"But this I confess unto thee, that after the way which they call heresy, so worship I the God of my fathers, believing all things which are written in the law and in the prophets:", insight:"After the way they call heresy; Paul wore their insult as his confession."},
  {q:"What hope did Paul share with his accusers?", options:["The resurrection of the dead, both of the just and unjust","The rebuilding of the temple","The coming of Elijah","An earthly kingdom for Israel"], a:0, ref:"Acts 24:15",verse:"And have hope toward God, which they themselves also allow, that there shall be a resurrection of the dead, both of the just and unjust.", insight:"Of the just and unjust; the resurrection is good news with a solemn edge."},
  {q:"What was Paul's daily exercise?", options:["To have always a conscience void of offence toward God, and toward men","To fast twice in the week","To pray three hours daily","To memorize the whole law"], a:0, ref:"Acts 24:16",verse:"And herein do I exercise myself, to have always a conscience void of offence toward God, and toward men.", insight:"A conscience void of offence; the clearest conscience is the busiest one."},
  {q:"Why had Paul come to Jerusalem after many years?", options:["To bring alms to his nation, and offerings","To stir up the people","To claim an inheritance","To see the high priest"], a:0, ref:"Acts 24:17",verse:"Now after many years I came to bring alms to my nation, and offerings.", insight:"Alms and offerings; he came with gifts, and they met him with chains."},
  {q:"In what state was Paul found in the temple?", options:["Purified, neither with multitude, nor with tumult","Armed, with a band of men","Disputing with the priests","Hiding from the soldiers"], a:0, ref:"Acts 24:18",verse:"Whereupon certain Jews from Asia found me purified in the temple, neither with multitude, nor with tumult.", insight:"Purified, no crowd, no tumult; the facts contradicted the frenzy."},
  {q:"Whose absence did Paul point out?", options:["The Jews from Asia who had found him in the temple","The chief captain Lysias","The elders of Jerusalem","The Roman centurions"], a:0, ref:"Acts 24:19",verse:"Who ought to have been here before thee, and object, if they had ought against me.", insight:"The real accusers stayed home; Paul asked why the witnesses were missing."},
  {q:"What single cry did Paul say he was judged for?", options:["Touching the resurrection of the dead I am called in question by you this day","I am a Pharisee, the son of a Pharisee","I appeal unto Caesar","God shall smite thee, thou whited wall"], a:0, ref:"Acts 24:21",verse:"Except it be for this one voice, that I cried standing among them, Touching the resurrection of the dead I am called in question by you this day.", insight:"One voice, one doctrine; the resurrection was the real charge all along."},
  {q:"How did Felix end the hearing?", options:["He deferred the case until Lysias should come down","He freed Paul at once","He sent Paul to Rome","He handed Paul to the Jews"], a:0, ref:"Acts 24:22",verse:"And when Felix heard these things, having more perfect knowledge of that way, he deferred them, and said, When Lysias the chief captain shall come down, I will know the uttermost of your matter.", insight:"He deferred them; delay is the coward's verdict."},
  {q:"What liberty did Felix grant Paul?", options:["Liberty, with friends free to visit and serve him","Freedom to leave the city","Leave to preach in Caesarea","Release from all charges"], a:0, ref:"Acts 24:23",verse:"And he commanded a centurion to keep Paul, and to let him have liberty, and that he should forbid none of his acquaintance to minister or come unto him.", insight:"Liberty with open doors; even a corrupt judge could not quite cage him."},
  {q:"Of what three things did Paul reason before Felix?", options:["Righteousness, temperance, and judgment to come","Faith, hope, and charity","Law, prophets, and psalms","Repentance, baptism, and grace"], a:0, ref:"Acts 24:25",verse:"And as he reasoned of righteousness, temperance, and judgment to come Felix trembled, and answered, Go thy way for this time; when I have a convenient season, I will call for thee.", insight:"Righteousness, temperance, judgment; Paul preached to a governor's conscience, not his curiosity."},
  {q:"What did the trembling Felix say?", options:["Go thy way for this time; when I have a convenient season, I will call for thee","What must I do to be saved?","Pray for me, Paul","I believe thy words are true"], a:0, ref:"Acts 24:25",verse:"And as he reasoned of righteousness, temperance, and judgment to come Felix trembled, and answered, Go thy way for this time; when I have a convenient season, I will call for thee.", insight:"A convenient season; the most dangerous words a trembling heart can speak."}
 ]},
{n:25, name:"I Appeal to Caesar",
 seal:{ref:"Acts 25:11",verse:"For if I be an offender, or have committed any thing worthy of death, I refuse not to die: but if there be none of these things whereof these accuse me, no man may deliver me unto them. I appeal unto Caesar."},
 facts:[
  "Did you know Paul's appeal to Caesar was a citizen's right? Once spoken, no governor could hand him to the mob; Festus had to send him to Rome (Acts 25:11-12).",
  "Did you know Bernice was Agrippa's sister? The 'great pomp' of Acts 25:23 masked a court steeped in scandal, yet even they would hear the gospel from a prisoner in chains.",
  "Did you know Festus summed up Christianity in one sentence? 'One Jesus, which was dead, whom Paul affirmed to be alive' (Acts 25:19). An outsider's summary, and the very heart of the faith."
 ],
 questions:[
  {q:"How soon after taking office did Festus go up to Jerusalem?", options:["After three days in the province","After three months","After one year","After forty days"], a:0, ref:"Acts 25:1",verse:"Now when Festus was come into the province, after three days he ascended from Caesarea to Jerusalem.", insight:"After three days; new rulers hurry to Jerusalem, and old hatreds were waiting."},
  {q:"What favor did the Jewish leaders ask of Festus?", options:["Send for Paul to Jerusalem, laying wait to kill him on the way","Release Paul at once","Send Paul to Rome","Let them judge Paul themselves"], a:0, ref:"Acts 25:3",verse:"And desired favour against him, that he would send for him to Jerusalem, laying wait in the way to kill him.", insight:"Desired favour; they dressed murder as a courtesy."},
  {q:"How did Festus answer?", options:["Paul should be kept at Caesarea, and he himself would depart shortly thither","Paul would be sent to Jerusalem","Paul would be freed at once","Paul would be sent to Rome"], a:0, ref:"Acts 25:4",verse:"But Festus answered, that Paul should be kept at Caesarea, and that he himself would depart shortly thither.", insight:"Kept at Caesarea; one plain refusal wrecked two years of plotting."},
  {q:"Who did Festus say should come down to accuse Paul?", options:["Those among them who were able, to go down with him","The whole council at once","Only the high priest","The Roman soldiers"], a:0, ref:"Acts 25:5",verse:"Let them therefore, said he, which among you are able, go down with me, and accuse this man, if there be any wickedness in him.", insight:"Let the able come down; justice asked the accusers to do the traveling."},
  {q:"How long did Festus tarry at Jerusalem?", options:["More than ten days","Three days","Forty days","Two years"], a:0, ref:"Acts 25:6",verse:"And when he had tarried among them more than ten days, he went down unto Caesarea; and the next day sitting on the judgment seat commanded Paul to be brought.", insight:"More than ten days; even governors must linger where hatred brews."},
  {q:"What was wrong with the Jews' many grievous complaints?", options:["They could not prove them","They were written in Greek","They concerned only money","They were against the wrong man"], a:0, ref:"Acts 25:7",verse:"And when he was come, the Jews which came down from Jerusalem stood round about, and laid many and grievous complaints against Paul, which they could not prove.", insight:"Many and grievous, yet unproved; volume is not evidence."},
  {q:"Against what three did Paul say he had done nothing?", options:["The law of the Jews, the temple, and Caesar","The council, the priests, and the people","Moses, the prophets, and the psalms","Jerusalem, Judea, and Samaria"], a:0, ref:"Acts 25:8",verse:"While he answered for himself, Neither against the law of the Jews, neither against the temple, nor yet against Caesar, have I offended any thing at all.", insight:"Neither law, nor temple, nor Caesar; a clean record on every front."},
  {q:"Why did Festus propose a trial at Jerusalem?", options:["Willing to do the Jews a pleasure","Commanded by Caesar","Advised by Agrippa","Required by Roman law"], a:0, ref:"Acts 25:9",verse:"But Festus, willing to do the Jews a pleasure, answered Paul, and said, Wilt thou go up to Jerusalem, and there be judged of these things before me?", insight:"To do the Jews a pleasure; pleasing men is the shortest road from justice."},
  {q:"Where did Paul say he ought to be judged?", options:["At Caesar's judgment seat","Before the council","In the temple courts","At Jerusalem"], a:0, ref:"Acts 25:10",verse:"Then said Paul, I stand at Caesar’s judgment seat, where I ought to be judged: to the Jews have I done no wrong, as thou very well knowest.", insight:"Caesar's judgment seat; the prisoner claimed the empire's highest court."},
  {q:"What words did Paul speak that changed everything?", options:["I appeal unto Caesar","I am innocent of all","God be my judge","Let me go free"], a:0, ref:"Acts 25:11",verse:"For if I be an offender, or have committed any thing worthy of death, I refuse not to die: but if there be none of these things whereof these accuse me, no man may deliver me unto them. I appeal unto Caesar.", insight:"I appeal unto Caesar; four words that carried the gospel to Rome."},
  {q:"How did Festus answer the appeal?", options:["Hast thou appealed unto Caesar? unto Caesar shalt thou go","Thy appeal is denied","Caesar will not hear thee","Wait until Lysias comes"], a:0, ref:"Acts 25:12",verse:"Then Festus, when he had conferred with the council, answered, Hast thou appealed unto Caesar? unto Caesar shalt thou go.", insight:"Unto Caesar shalt thou go; man's sentence became God's itinerary."},
  {q:"Who came to Caesarea to salute Festus?", options:["King Agrippa and Bernice","Herod and Herodias","Felix and Drusilla","Lysias and the elders"], a:0, ref:"Acts 25:13",verse:"And after certain days king Agrippa and Bernice came unto Caesarea to salute Festus.", insight:"Agrippa and Bernice; royalty came calling, and the gospel got a royal audience."},
  {q:"How did Festus describe Paul to Agrippa?", options:["A certain man left in bonds by Felix","A dangerous rebel of Judea","A teacher of the Nazarenes","A Roman citizen wronged"], a:0, ref:"Acts 25:14",verse:"And when they had been there many days, Festus declared Paul’s cause unto the king, saying, There is a certain man left in bonds by Felix:", insight:"A certain man left in bonds; two years forgotten in a prison, remembered by God."},
  {q:"What did Festus call the manner of the Romans?", options:["No man is delivered to die before facing his accusers and answering for himself","The accused must pay for his trial","Prisoners are sent to Rome at once","The governor decides alone"], a:0, ref:"Acts 25:16",verse:"To whom I answered, It is not the manner of the Romans to deliver any man to die, before that he which is accused have the accusers face to face, and have licence to answer for himself concerning the crime laid against him.", insight:"Face to face; even pagan law guarded what Paul's enemies denied him."},
  {q:"How did Festus sum up the case to Agrippa?", options:["Questions of their superstition, and one Jesus, dead, whom Paul affirmed to be alive","Treason against Caesar Augustus","Theft from the temple treasury","Rebellion throughout Judea"], a:0, ref:"Acts 25:19",verse:"But had certain questions against him of their own superstition, and of one Jesus, which was dead, whom Paul affirmed to be alive.", insight:"One Jesus, dead, whom Paul affirmed alive; an outsider stated the gospel in a sentence."},
  {q:"What did Agrippa say when he heard Paul's case?", options:["I would also hear the man myself","Send him to Rome at once","Free him without delay","Let the Jews judge him"], a:0, ref:"Acts 25:22",verse:"Then Agrippa said unto Festus, I would also hear the man myself. To morrow, said he, thou shalt hear him.", insight:"I would also hear the man myself; curiosity opened a door for the gospel."},
  {q:"How did Agrippa and Bernice enter the hearing?", options:["With great pomp, with chief captains and principal men of the city","Quietly, with a few servants","In chains, as prisoners","At midnight, in secret"], a:0, ref:"Acts 25:23",verse:"And on the morrow, when Agrippa was come, and Bernice, with great pomp, and was entered into the place of hearing, with the chief captains, and principal men of the city, at Festus’ commandment Paul was brought forth.", insight:"With great pomp; earthly glory filed in to hear a prisoner in chains."},
  {q:"What had the Jews been crying about Paul?", options:["That he ought not to live any longer","That he should be scourged","That he must leave Judea","That he should pay tribute"], a:0, ref:"Acts 25:24",verse:"And Festus said, King Agrippa, and all men which are here present with us, ye see this man, about whom all the multitude of the Jews have dealt with me, both at Jerusalem, and also here, crying that he ought not to live any longer.", insight:"Not live any longer; the old cry followed him from Jerusalem to Caesarea."},
  {q:"What was Festus's own finding about Paul?", options:["He had committed nothing worthy of death","He was guilty of sedition","He had profaned the temple","He deserved the scourge"], a:0, ref:"Acts 25:25",verse:"But when I found that he had committed nothing worthy of death, and that he himself hath appealed to Augustus, I have determined to send him.", insight:"Nothing worthy of death; the judge's own verdict cleared the prisoner he kept."},
  {q:"What seemed unreasonable to Festus?", options:["To send a prisoner to Caesar without signifying the crimes laid against him","To keep Paul bound so long","To trouble Agrippa with the case","To hold a trial at Caesarea"], a:0, ref:"Acts 25:27",verse:"For it seemeth to me unreasonable to send a prisoner, and not withal to signify the crimes laid against him.", insight:"Unreasonable; the empire needed a charge, and the gospel supplied none."}
 ]}
]);
